@Composable
fun FeedScreen(uiState: FeedUiState) {
    // Derived value recomputes only when uiState.items changes identity.
    val visible by remember(uiState.items) {
        derivedStateOf { uiState.items.filter { it.visible } }
    }
    LazyColumn {
        items(visible, key = { it.id }) { item -> FeedRow(item) }
    }
}

