class FeedPrefetcher(private val repo: FeedRepository) {
    fun onFeedFocused() {
        repo.prefetchNextPage()   // user is here, scrolling — consumption is likely
    }
    // Prefetch at cold start for a screen the user may never reach is waste.
}

// Deferred, batched, constraint-aware — the wakelock replacement.
WorkManager.getInstance(context).enqueueUniquePeriodicWork(
    "sync", ExistingPeriodicWorkPolicy.UPDATE,
    PeriodicWorkRequestBuilder<SyncWorker>(15, TimeUnit.MINUTES)
        .setConstraints(Constraints.Builder().setRequiresBatteryNotLow(true).build())
        .build()
)

// A bounded partial wakelock when one is genuinely required.
val lock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "upload")
lock.acquire(30_000)                       // hard ceiling — never unbounded
try { upload() } finally { if (lock.isHeld) lock.release() }

